use shodo::{LayoutContext, limits::Limits, hit::{LineLayout,TextPosition}, mapping::Affinity};
use shodo_bench::{Workload, Operation, layout, digest};
use std::hint::black_box;
#[cfg(feature="allocation-counting")]
#[global_allocator]
static ALLOC: shodo_bench::allocator::CountingAllocator<std::alloc::System> = shodo_bench::allocator::CountingAllocator::new(std::alloc::System);
#[inline(never)]
fn profile_once(execute: &mut dyn FnMut()) { black_box(execute)(); }
fn main() {
 let args:Vec<_>=std::env::args().skip(1).collect();
 let mode=&args[0]; let scale:usize=args[2].parse().unwrap();
 let repeat:usize=args[3].parse().unwrap(); let count:usize=args.get(4).map_or(21,|s|s.parse().unwrap()); let warm:usize=args.get(5).map_or(3,|s|s.parse().unwrap());
 assert!(repeat>0&&count>0);
 let mut w=if args[1]=="plain" {Workload::named("latin-short",1).unwrap()}else{Workload::named(&args[1],scale).unwrap()};
 if args[1]=="plain" {w.id="plain".into();w.scale=scale;w.text="a".repeat(scale);w.width=1_000_000.0;}
 let limits=Limits::default();let fonts=shodo_fixtures::load_fonts(&limits).unwrap(); let mut cx=LayoutContext::new();
 let ps=w.build(&mut cx,&fonts,&limits).unwrap();assert!(ps.iter().all(|p|p.warnings().is_empty()));
 let run=layout(&w,&ps,&mut cx,&fonts,&limits,Operation::AllLines).unwrap();assert!(cx.take_warnings().is_empty());
 let expected=digest(&run,&fonts).unwrap();let index=LineLayout::new(&run.lines);
 let endpoints:Vec<_>=run.lines.iter().enumerate().map(|(line,l)|{let r=l.text_range();(TextPosition{line,offset:r.start as u32,affinity:Affinity::Downstream},TextPosition{line,offset:r.end as u32,affinity:Affinity::Upstream})}).collect();
 let paint=||run.lines.iter().map(|l|l.paint_spans()).collect::<Vec<_>>();
 let selection=||endpoints.iter().map(|&(a,b)|index.selection_rects(a,b)).collect::<Vec<_>>();
 let paint_before=format!("{:?}",paint());let selection_before=format!("{:?}",selection());
 #[cfg(feature="shared-geometry")]
 assert_eq!(paint_before,format!("{:?}",run.lines.iter().enumerate().map(|(i,_)|index.paint_spans(i).unwrap()).collect::<Vec<_>>()));
 let coordinate_hits = if matches!(mode.as_str(), "first-hit" | "all-line-hits") {
  let fresh = LineLayout::new(&run.lines);
  let first = run.lines.first().map(|line| fresh.hit_test(0.0, line.block_offset()));
  let all:Vec<_> = run.lines.iter().map(|line| LineLayout::new(std::slice::from_ref(line)).hit_test(0.0,line.block_offset())).collect();
  format!("{first:?}/{all:?}")
 } else {String::new()};
 use sha2::Digest as _;
 let validation=serde_json::json!({"paint_sha256":format!("{:x}",sha2::Sha256::digest(paint_before.as_bytes())),"selection_sha256":format!("{:x}",sha2::Sha256::digest(selection_before.as_bytes())),"coordinate_hits_sha256":format!("{:x}",sha2::Sha256::digest(coordinate_hits.as_bytes()))});
 let mut execute=||match mode.as_str(){
  "build"=>{black_box(w.build(&mut cx,&fonts,&limits).unwrap());},
  "layout"=>{black_box(layout(&w,&ps,&mut cx,&fonts,&limits,Operation::AllLines).unwrap());},
  "cold"=>{let mut fresh=LayoutContext::new();black_box(layout(&w,&ps,&mut fresh,&fonts,&limits,Operation::AllLines).unwrap());assert!(fresh.take_warnings().is_empty());},
  "widths"=>{black_box(layout(&w,&ps,&mut cx,&fonts,&limits,Operation::ReuseWidths).unwrap());},
  "intrinsic"=>{black_box(layout(&w,&ps,&mut cx,&fonts,&limits,Operation::Intrinsic).unwrap());},
  #[cfg(feature="shared-geometry")]
  "shared-paint"=>{black_box(run.lines.iter().enumerate().map(|(i,_)|index.paint_spans(i).unwrap()).collect::<Vec<_>>());},
  #[cfg(feature="shared-geometry")]
  "combined-shared"=>{let shared=LineLayout::new(black_box(&run.lines));black_box(run.lines.iter().enumerate().map(|(i,_)|shared.paint_spans(i).unwrap()).collect::<Vec<_>>());},
  "first-hit"=>{let hit=LineLayout::new(black_box(&run.lines));if let Some(line)=run.lines.first(){black_box(hit.hit_test(0.0,line.block_offset()));}},
  "all-line-hits"=>{for line in &run.lines{let hit=LineLayout::new(black_box(std::slice::from_ref(line)));black_box(hit.hit_test(0.0,line.block_offset()));}},
  "index"=>{black_box(LineLayout::new(black_box(&run.lines)));},
  "paint"=>{black_box(paint());},
  "combined"=>{black_box(paint());black_box(LineLayout::new(black_box(&run.lines)));},
  "selection"=>{black_box(selection());},
  "overflow"=>{black_box(run.lines.iter().map(|l|l.overflow_rect()).collect::<Vec<_>>());},
  _=>panic!("mode")};
 for _ in 0..warm {execute();}
 #[cfg(not(feature="allocation-counting"))]
 let samples:Vec<_>=(0..count).map(|_|{let t=std::time::Instant::now();for _ in 0..repeat {profile_once(&mut execute);}t.elapsed().as_nanos() as f64/repeat as f64}).collect();
 #[cfg(feature="allocation-counting")]
 let samples:Vec<_>=(0..3).map(|_|{let s=ALLOC.begin().unwrap();for _ in 0..repeat {profile_once(&mut execute);}s.finish()}).collect();
 drop(execute);
 let after=layout(&w,&ps,&mut cx,&fonts,&limits,Operation::AllLines).unwrap();assert_eq!(expected,digest(&after,&fonts).unwrap());assert_eq!(paint_before,format!("{:?}",paint()));assert_eq!(selection_before,format!("{:?}",selection()));
 let warnings=cx.take_warnings();assert!(warnings.is_empty());
 println!("{}",serde_json::json!({"mode":mode,"case":w.id,"scale":w.scale,"repeat":repeat,"samples":samples,"digest":expected,"warning_count":warnings.len(),"context":format!("{cx:?}"),"validation":validation}));
}

