import json,pathlib,subprocess,statistics,hashlib
root=pathlib.Path(__file__).parent
scenes=[('latin-long',64),('japanese-long',64),('arabic-long',8),('arabic-long',64),('many-short-latin',64),('mixed-scripts',8),('justify',64),('plain',1024)]
variants={
 'geometry':[(a,b,c,s) for a,b in [('combined','combined-shared'),('paint','shared-paint')] for c,s in scenes]+[('combined','combined','latin-long',64),('paint','paint','plain',1024)],
 'edge':[(o,o,c,s) for o,c,s in [('layout','arabic-long',8),('layout','arabic-long',64),('layout','latin-long',64),('layout','many-short-latin',64),('layout','japanese-long',64),('widths','arabic-long',8),('widths','arabic-long',64),('widths','latin-long',64),('widths','many-short-latin',64),('cold','arabic-long',64)]],
 'spacing':[(o,o,c,s) for o,c,s in [('layout','latin-long',64),('layout','japanese-long',64),('layout','arabic-long',8),('layout','arabic-long',64),('layout','many-short-latin',64),('layout','mixed-scripts',8),('layout','justify',64),('intrinsic','latin-long',64),('intrinsic','japanese-long',64),('cold','latin-long',64)]],
 'lazy':[(o,o,c,s) for o in ['index','first-hit'] for c,s in scenes]+[('all-line-hits','all-line-hits',c,s) for c,s in [('latin-long',64),('japanese-long',64),('arabic-long',64)]]}
variants['combined']=[('combined','combined-shared',c,s) for c,s in scenes]+[(o,o,c,s) for o,c,s in [('layout','latin-long',64),('layout','japanese-long',64),('layout','arabic-long',8),('layout','arabic-long',64),('widths','arabic-long',8),('widths','arabic-long',64),('index','latin-long',64),('first-hit','arabic-long',64),('all-line-hits','latin-long',64)]]
variants['control']=[(o,o,c,s) for o,c,s in [('paint','plain',1024),('layout','latin-long',64),('layout','arabic-long',64),('index','latin-long',64)]]
rows=json.loads((root/'paired-times.json').read_text()) if (root/'paired-times.json').exists() else []
done={(r['variant'],r['before_op'],r['after_op'],r['case'],r['scale']) for r in rows}
for variant,conditions in variants.items():
 for before,after,case,scale in conditions:
  if (variant,before,after,case,scale) in done:continue
  samples={'baseline':[],'candidate':[]};repeat=20 if case=='plain' else 1
  for pair in range(3):
   for label in (['baseline','candidate'] if pair%2==0 else ['candidate','baseline']):
    exe=root/(('baseline' if label=='baseline' else variant)+'-time');op=before if label=='baseline' else after
    d=json.loads(subprocess.check_output(['taskset','-c','2',str(exe),op,case,str(scale),str(repeat),'21','3'],text=True))
    assert d['warning_count']==0 and d['digest']['synthetic_glyphs']==0
    samples[label].append(d)
  want=samples['baseline'][0]['digest']
  assert all(d['digest']==want and d['validation']==samples['baseline'][0]['validation'] for groups in samples.values() for d in groups)
  med={k:statistics.median(n for d in groups for n in d['samples']) for k,groups in samples.items()}
  row={'variant':variant,'before_op':before,'after_op':after,'case':case,'scale':scale,'samples':samples,'median_ns':med,'ratio':med['candidate']/med['baseline']}
  rows.append(row);(root/'paired-times.json').write_text(json.dumps(rows,ensure_ascii=False))
  print(json.dumps({'variant':variant,'before_op':before,'after_op':after,'case':case,'scale':scale,'baseline_ms':round(med['baseline']/1e6,4),'candidate_ms':round(med['candidate']/1e6,4),'ratio':round(row['ratio'],4)},ensure_ascii=False),flush=True)

